    left_arm = sphere("Left arm sleeve", (-0.39, 0, 0.91), (0.08, 0.085, 0.23), teal)
    rigid_skin(left_arm, rig, "upper_arm.L")
    left_hand = sphere("Left hand", (-0.43, -0.025, 0.58), (0.09, 0.085, 0.10), ceramic)
